const EXT={unfunded:"Unfunded",rule:"Rule violation",unmapped:"Unmapped",lowconf:"Low confidence",split:"Split mismatch",cash:"Cash overspend",recon:"Reconciliation",lapse:"Lapse",headroom:"Headroom"};
const ACCT_FUND={"6510":"230","6110":"320","6310":"230","6420":"320","1710":"210","1720":"210"};
function cashForm(srcId){const s=F.sources.find(x=>x.id===srcId);if(!s)return;const b=balances().src[srcId]||{};
 openForm({id:"fin_cash_f",title:"Record cash received on "+srcId,story:"Cash-based colors may spend only what has been received (rule V5). Spend to date is "+U(b.spend||0)+" against cash received of "+U(s.cash||0)+". Receipt evidence is kept with the entry.",submit:"Record receipt",fields:[{k:"amt",label:"Amount received",type:"money",req:true,step:1000},{k:"evid",label:"Evidence",type:"text",req:true,ph:"Remittance advice 2026-10-08"}],defaults:{amt:Math.max(0,(b.spend||0)-(s.cash||0)),evid:""},
 onSubmit:v=>{const a=+v.amt||0;if(a<=0)return fail("fin_cash_f","amt","Amount must be above zero");s.cash=(s.cash||0)+a;logE("cash",srcId,"Cash received "+U(a)+" on "+srcId,v.evid,"Controller");touch();audit("recorded cash receipt",srcId+" "+U(a));closeDrawer();render();return{toast:"Cash receipt recorded"}}})}
function extendForm(srcId){const s=F.sources.find(x=>x.id===srcId);if(!s)return;
 openForm({id:"fin_ext_f",title:"Extend the end date of "+srcId,story:"Extending a source avoids a lapse but needs the grantor's written agreement and the color's approval authority ("+(colorOf(s.color)||{}).auth+"). Current end date: "+(s.end?dt(s.end):"none")+".",submit:"Extend",fields:[{k:"end",label:"New end date",type:"date",req:true},{k:"evid",label:"Evidence of the grantor's agreement",type:"text",req:true}],defaults:{end:s.end?String(+s.end.slice(0,4)+1)+s.end.slice(4):"",evid:""},
 onSubmit:v=>{if(s.end&&v.end<=s.end)return fail("fin_ext_f","end","The new date must be after "+dt(s.end));const old=s.end;s.end=v.end;logE("source",srcId,"End date extended from "+dt(old)+" to "+dt(v.end),v.evid,(colorOf(s.color)||{}).auth);touch();audit("extended source end date",srcId);closeDrawer();render();return{toast:"Source extended"}}})}
function excForm(id){const x=exceptions().find(e=>e.id===id);if(!x)return;
 openForm({id:"fin_exc_f",title:"Update exception",story:x.title+". Status is kept here; the exception itself is derived from live rules, so it only disappears when the condition is fixed. Accepting a risk keeps it visible with your note.",submit:"Save",fields:[{k:"owner",label:"Owner",type:"people",req:true},{k:"status",label:"Status",type:"chips",opts:["Open","In progress","Accepted risk"]},{k:"note",label:"Note",type:"longtext"}],defaults:{owner:x.owner,status:x.status,note:x.note},
 onSubmit:v=>{F.exc[id]=Object.assign(F.exc[id]||{},{owner:v.owner,status:v.status,note:v.note,opened:x.opened});logE("exception",id,"Exception updated: "+v.status+", owner "+v.owner,v.note);touch();audit("updated exception",id+" "+v.status);closeDrawer();render();return{toast:"Exception updated"}}})}
function fixAction(a,x){const l=lineById(x.ref);
 switch(a){case"assign":{if(!l)return;const res=spendCost({amt:l.fcst,nature:l.nature,gate:assignGate(l),cons:l.cons,date:TODAY,ctx:ctxOf(l)});if(!res.splits.length){toast("No color can fund "+x.ref+" today. See the spend-order simulator for why.","warn");go("fin_spend");return}
   recolorForm(x.ref);break}
  case"recolor":recolorForm(x.ref);break;case"map":mapForm(x.ref);break;case"review":reviewForm(x.ref);break;
  case"rebalance":rebalance(x.ref.replace(/^sp-/,""));closeDrawer();break;
  case"cash":cashForm(x.ref.replace(/^c-/,""));break;
  case"offset":{const acct=x.ref.replace(/^gl-/,"");H.offsetForm?H.offsetForm(ACCT_FUND[acct]||"230"):toast("Open Color of money","info");break}
  case"lapse":{const c=x.ref.replace(/^lapse-/,"");const s=F.sources.find(y=>y.color===c&&y.end);if(s)extendForm(s.id);break}
  case"headroom":closeDrawer();colorDrawer(x.ref.replace(/^head-/,""));break}}
const FIXL={assign:"Assign a color",recolor:"Change the color",map:"Fix the mapping",review:"Open a review item",rebalance:"Rebalance the split",cash:"Record cash received",offset:"Record a timing offset",lapse:"Extend the source",headroom:"Open the color"};
function openExc(id){const x=exceptions().find(e=>e.id===id);if(!x)return;
 openDrawer(`<div class="eyebrow">Exception · ${E(EXT[x.type]||x.type)}</div><h2 style="margin:4px 0">${E(x.title)}</h2><div class="row">${pill_(x.sev==="bad"?"Needs action":"Review",x.sev)}${pill_(x.status,x.status==="Open"?"warn":x.status==="In progress"?"info":"mute")}</div>
 <div class="story">${E(x.detail)}</div>${dtl([["Reference",`<code>${E(x.ref)}</code>`],["Owner",who_(x.owner)],["Opened",dt(x.opened)],["Note",E(x.note||"None")]])}
 <div class="row" style="margin-top:10px">${x.fix?`<button class="btn primary" data-fin2="fix" data-id="${E(x.id)}" data-a="${x.fix}">${E(FIXL[x.fix])}</button>`:""}<button class="btn" data-fin2="excedit" data-id="${E(x.id)}">Owner and status</button></div>`)}
