document.addEventListener("click",e=>{const t=e.target.closest("[data-fin2]");if(!t)return;const a=t.dataset.fin2,id=t.dataset.id;
 switch(a){
  case"recolor":closeDrawer();recolorForm(id);break;
  case"mapline":closeDrawer();mapForm(id);break;
  case"narr":closeDrawer();narrForm(id);break;
  case"thresholds":threshForm();break;
  case"rerun":touch();toast("Forecast rerun: "+KK(forecast().shifted)+" shifted, "+KK(forecast().unfunded)+" unfunded","info");audit("reran color-aware forecast","");render();break;
  case"caldone":{F.cal.done[id]=!F.cal.done[id];logE("calendar",id,F.cal.done[id]?"Cycle marked done":"Cycle reopened","");touch();audit("cadence calendar",id+(F.cal.done[id]?" done":" reopened"));render();break}
  case"trigger":{logE("trigger",id,"Reforecast trigger recorded: "+id,"Forecast marked for refresh");touch();audit("reforecast trigger",id);toast("Trigger logged; the forecast will be refreshed","info");break}
  case"proj":projDrawer(id);break;
  case"advance":closeDrawer();moveForm(id,t.dataset.to);break;
  case"qok":approveQ(id,true);break;
  case"qno":approveQ(id,false);break;
  case"relg3":{const p=t.dataset.p,c=t.dataset.c;relForm({color:c,trig:"capital",src:pickSrc(c),proj:p,date:TODAY,evid:"Asset register entry at go-live",amt:Math.round(+t.dataset.amt||0)});break}
  case"cons":consDrawer(id);break;
  case"drvnew":closeDrawer();drvForm(id);break;
  case"drvok":drvApprove(id,+t.dataset.v);closeDrawer();break;
  case"splitnew":splitForm();break;
  case"spok":splitApprove(id);break;
  case"spundo":splitUndo(id);break;
  case"rebal":rebalance(id);break;
  case"sign":signLadder(id,t.dataset.n);break;
  case"fix":{const x=exceptions().find(z=>z.id===id)||{id,ref:t.dataset.ref,type:""};if(t.dataset.ref)x.ref=t.dataset.ref;fixAction(t.dataset.a,x);break}
  case"excedit":closeDrawer();excForm(id);break;
  case"runrules":{F.lastRun=TODAY;touch();const v=validate();audit("ran validation rules",v.filter(x=>!x.fail).length+" of 10 pass");toast(v.filter(x=>!x.fail).length+" of 10 rules pass; "+sum(v,x=>x.fail)+" items to fix","info");render();break}
  case"evtog":{const c=colorOf(id);F.evid[id]=F.evid[id]||{};F.evid[id][t.dataset.k]=!F.evid[id][t.dataset.k];logE("evidence",id,(F.evid[id][t.dataset.k]?"Evidence on file: ":"Evidence withdrawn: ")+t.dataset.k.replace(/_/g," "),"",c&&c.auth);touch();audit("evidence set",id+" "+t.dataset.k);render();break}
  case"poledit":polForm(id);break}});
document.addEventListener("change",e=>{const t=e.target.closest("[data-fin2-change]");if(!t)return;const a=t.dataset.fin2Change,v=t.value;
 if(a==="gt"){F.gt[t.dataset.k]=v;render()}
 else if(a==="func"){const b=F.func[t.dataset.id];F.func[t.dataset.id]=v;logE("func",t.dataset.id,"Functional class "+b+" to "+v,"Decision D-04 placeholder","Controller");touch();audit("functional class",t.dataset.id+" "+b+" to "+v);render()}});

