let wired=0;
function wire(){if(wired>=3)return;
 try{const M=window.MODMAP;if(M&&M.addModule&&!wired){
   const mods=[["fin_model","IT financial model",["fin_color","fin_funding_line"],["fin_exception"]],["fin_color","Color of money",["fin_color","fin_color_source","fin_color_nature_rule"],["fin_color_balance","fin_release_event"]],["fin_spend","Spend-order simulator",["fin_color_nature_rule","fin_spend_order_policy"],["fin_funding_line"]],["fin_budget","Budget and forecast",["fin_funding_line","fin_color_balance"],["fin_funding_line"]],["fin_gates","Funding gates",["fin_gate","fin_project_funding"],["fin_funding_line","fin_gate"]],["fin_alloc","Allocation and showback",["fin_allocation_driver","fin_funding_line"],["fin_allocation_driver"]],["fin_rules","Financial controls",["fin_exception","fin_mapping_record"],["fin_exception"]]];
   const own={fin_model:"Controller",fin_color:"Controller",fin_spend:"Controller",fin_budget:"Finance controller",fin_gates:"CFO office",fin_alloc:"TBM lead",fin_rules:"Controller"};
   mods.forEach(m=>{try{if(!window.MODMAP.addModule({id:m[0],name:m[1],band:"mon",own:own[m[0]],r:m[2],w:m[3],proposed:false,flows:[]}).ok){}}catch(e){}});
   const fl=[
    {from:"ppm_proj",to:"fin_gates",data:"Project and gate request",entity:"project",mode:"event",trig:"Project reaches a gate"},
    {from:"fin_gates",to:"bud_over",data:"Funding line for the project",entity:"fin_funding_line",mode:"event",trig:"Gate G1 approved"},
    {from:"fin_color",to:"inv",data:"Funding color and rule result for invoice coding",entity:"fin_funding_line",mode:"api",trig:"Invoice approval"},
    {from:"ppm_sow",to:"bud_model",data:"Contract renewal for the forecast",entity:"contract",mode:"batch",trig:"Renewal date within 12 months"},
    {from:"ppm_sow",to:"bud_ven",data:"Contract renewal for vendor management",entity:"contract",mode:"event",trig:"Renewal date within 12 months"},
    {from:"ppm_sow",to:"bud_ben",data:"Contract renewal for benefits tracking",entity:"contract",mode:"batch",trig:"Renewal date within 12 months"},
    {from:"bud_over",to:"fin_budget",data:"Budget lines, reserve draws and contracts",entity:"fin_funding_line",mode:"event",trig:"Budget line changes"},
    {from:"tbm_model",to:"fin_alloc",data:"Cost pools, towers and consumers",entity:"cost_allocation",mode:"batch",trig:"Monthly TBM refresh"},
    {from:"fin_gates",to:"fin_color",data:"Release event at placed in service",entity:"fin_release_event",mode:"event",trig:"Gate G3 approved"},
    {from:"fin_color",to:"fin_budget",data:"Color balances and headroom",entity:"fin_color_balance",mode:"event",trig:"Balance changes"},
    {from:"fin_budget",to:"bud_model",data:"Color-aware forecast and variance narratives",entity:"fin_color_balance",mode:"event",trig:"Forecast saved"},
    {from:"fin_model",to:"fin_color",data:"Decisions and policy versions",entity:"fin_spend_order_policy",mode:"human",trig:"Decision recorded"},
    {from:"fin_color",to:"fin_spend",data:"Rule matrix, sources and balances",entity:"fin_color_nature_rule",mode:"api",trig:"On each spend-order run"},
    {from:"fin_spend",to:"fin_gates",data:"Proposed color and rationale at G1",entity:"fin_funding_line",mode:"api",trig:"Gate G1 request"},
    {from:"fin_alloc",to:"fin_rules",data:"Split sums for rule V2",entity:"fin_allocation_driver",mode:"event",trig:"Split saved"},
    {from:"fin_rules",to:"fin_model",data:"Rule results and exceptions",entity:"fin_exception",mode:"event",trig:"Rules run"}];
   const r=window.MODMAP.addFlows(fl);if(r&&r.ok!==false)wired=1}}catch(e){}
 try{const P=window.PROCLIB;if(P&&P.addProcess&&wired===1){const modOf={budget_cycle:"fin_budget",quarterly_reforecast:"fin_budget",color_assignment:"fin_color",gl_reconciliation:"fin_rules",release_event:"fin_color",variance_review:"fin_budget"};
   FIN.procs.forEach(p=>{try{const k=String(p.id).replace(/^fin\./,"");P.addProcess({id:p.id,name:p.name,module:modOf[k]||"fin_budget",family:"Money and contracts",owner:p.owner,trigger:p.trigger,steps:p.steps,inputs:[p.trigger],outputs:[p.steps.length?p.steps[p.steps.length-1].out:""],entities:["fin_color","fin_funding_line"],metrics:["m_fin_colored","m_fin_rules","m_fin_recon"],model:"CMMI",target:3})}catch(e){}});wired=2}}catch(e){}}
